// NTC ile sıcaklık ölçme (yaklaşık): 30 °C ve üstünde LED yanar
const int NTC_PIN = A0;   // 5V - 10k direnç - A0 - NTC - GND
const int LED = 8;
const float ESIK = 30.0;  // °C

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int adc = analogRead(NTC_PIN);

  // İki kalibrasyon noktası: 20 °C ≈ 569, 40 °C ≈ 355 (10 kΩ NTC, B=3950)
  // Aralarında doğrusal yaklaşım yapıyoruz (20-40 °C arası yaklaşık doğru)
  float sicaklik = 20.0 + (569.0 - adc) * 20.0 / (569.0 - 355.0);

  Serial.print("ADC: ");
  Serial.print(adc);
  Serial.print("  Sicaklik: ");
  Serial.println(sicaklik);

  if (sicaklik >= ESIK) {
    digitalWrite(LED, HIGH);
  } else {
    digitalWrite(LED, LOW);
  }
  delay(500);
}
